import test from 'node:test'
import assert from 'node:assert/strict'
import { deliver } from '../src/webhooks/deliver.js'

test('retries three times with backoff', async () => {
  let calls = 0
  const fetchStub = async () => { calls++; return { ok: calls === 4 } }
  await deliver({ url: 'https://example.com/hook' }, { fetch: fetchStub, backoffMs: 50 })
  assert.equal(calls, 4)
})
export async function deliver(hook, { fetch, backoffMs = 1000, attempts = 4 } = {}) {
  for (let i = 0; i < attempts; i++) {
    const res = await fetch(hook.url, { method: 'POST' })
    if (res.ok) return true
    await new Promise((r) => setTimeout(r, backoffMs * 2 ** i + Math.random() * backoffMs))
  }
  return false
}
